@dataclass(frozen=True, kw_only=True)
class ModelArchitecture(Declaration):
    vocabulary: int = 384
    width: int = 8
    ffn: int = 16
    context: int = 128
    layers: int = 1
    heads: int = 1
    epsilon: float = 1e-05
    position: str = 'learned-absolute'
    normalization: str = 'pre-layernorm'
    activation: str = 'gelu-tanh'
    precision: str = 'binary64'


@dataclass(frozen=True, kw_only=True)
class ModelArtifact(Declaration):
    checkpoint_sha256: str
    tokenizer_sha256: str
    architecture: ModelArchitecture = field(default_factory=ModelArchitecture)


@dataclass(frozen=True, kw_only=True)
class InferenceSystem(Declaration):
    execution: str = 'full-prefix-recomputation'
    max_new_tokens_cap: int = 8
    max_requests: int = 1
    arrival_policy: str = 'single-at-zero'


@dataclass(frozen=True, kw_only=True)
class GenerationPolicy(Declaration):
    max_new_tokens: int = 6
    selection: str = 'greedy-lowest-id-tie'
    stopping: str = 'turn-end-or-budget'


@dataclass(frozen=True, kw_only=True)
class InferenceRequest(Declaration):
    text: str = 'the ball is in'
    generation: GenerationPolicy = field(default_factory=GenerationPolicy)


@dataclass(frozen=True, kw_only=True)
class RunOutcome(Declaration):
    selected_tokens: int
    delivered_tokens: int
    unused_budget: int
    stop_reason: str
    complete: bool


@dataclass(frozen=True, kw_only=True)
class InspectionState(Declaration):
    run_id: str
    prediction: int
    position: int


@dataclass(frozen=True, kw_only=True)
class RequestBinding(Declaration):
    model: ModelArtifact
    system: InferenceSystem = field(default_factory=InferenceSystem)
    request: InferenceRequest = field(default_factory=InferenceRequest)


@dataclass(frozen=True, kw_only=True)
class ScheduledRequest(Declaration):
    request_id: str
    arrival_us: int
    request: InferenceRequest = field(default_factory=InferenceRequest)


@dataclass(frozen=True, kw_only=True)
class Workload(Declaration):
    kind: str = 'fixed-arrivals'
    requests: tuple[ScheduledRequest, ...]


@dataclass(frozen=True, kw_only=True)
class RunBinding(Declaration):
    model: ModelArtifact
    system: InferenceSystem = field(default_factory=InferenceSystem)
    workload: Workload


@dataclass(frozen=True, kw_only=True)
class EventClock(Declaration):
    kind: str = 'execution-order'


@dataclass(frozen=True, kw_only=True)
class RequestArrived(Declaration):
    kind: str = 'request-arrived'
    arrival_us: int


@dataclass(frozen=True, kw_only=True)
class InputEncoded(Declaration):
    kind: str = 'input-encoded'
    input_sha256: str
    token_count: int


@dataclass(frozen=True, kw_only=True)
class WorkCompleted(Declaration):
    kind: str = 'work-completed'
    work_id: str
    phase: str


@dataclass(frozen=True, kw_only=True)
class TokenSelected(Declaration):
    kind: str = 'token-selected'
    work_id: str
    token_id: int
    output_position: int


@dataclass(frozen=True, kw_only=True)
class TokenCommitted(Declaration):
    kind: str = 'token-committed'
    work_id: str
    token_ids: tuple[int, ...]
    output_start: int


@dataclass(frozen=True, kw_only=True)
class TokenDelivered(Declaration):
    kind: str = 'token-delivered'
    work_id: str
    token_ids: tuple[int, ...]
    output_start: int
    display_delta: str


@dataclass(frozen=True, kw_only=True)
class RequestFinished(Declaration):
    kind: str = 'request-finished'
    outcome: RunOutcome


@dataclass(frozen=True, kw_only=True)
class RunEvent(Declaration):
    event_id: str
    run_id: str
    request_id: str
    sequence: int
    causes: tuple[str, ...]
    payload: RequestArrived | InputEncoded | WorkCompleted | TokenSelected | TokenCommitted | TokenDelivered | RequestFinished


@dataclass(frozen=True, kw_only=True)
class NumericalTrace(Declaration):
    checkpoint: dict[str, Any]
    code: dict[str, Any]
    contract_sha256: str
    declaration: RequestBinding
    decoding_contract: dict[str, Any]
    evidence: str
    format: str
    id: str
    outcome: RunOutcome
    output_ids: tuple[int, ...]
    output_display: str
    passes: tuple[dict[str, Any], ...]
    precision: dict[str, Any]
    request_id: str
    sequence_ids: tuple[int, ...]
    tokenizer: dict[str, Any]
    vocabulary: tuple[dict[str, Any], ...]


@dataclass(frozen=True, kw_only=True)
class RunRecord(Declaration):
    format: str = 'workload-run-v1'
    id: str
    contract_sha256: str
    declaration: RunBinding
    clock: EventClock = field(default_factory=EventClock)
    events: tuple[RunEvent, ...]
    traces: tuple[NumericalTrace, ...]


@dataclass(frozen=True, kw_only=True)
class Capabilities(Declaration):
    engine: str = 'workload-engine-v1'
    contract_sha256: str


@dataclass(frozen=True, kw_only=True)
class ApiError(Declaration):
    error: str


MODELS = {'ModelArchitecture': ModelArchitecture, 'ModelArtifact': ModelArtifact, 'InferenceSystem': InferenceSystem, 'GenerationPolicy': GenerationPolicy, 'InferenceRequest': InferenceRequest, 'RunOutcome': RunOutcome, 'InspectionState': InspectionState, 'RequestBinding': RequestBinding, 'ScheduledRequest': ScheduledRequest, 'Workload': Workload, 'RunBinding': RunBinding, 'EventClock': EventClock, 'RequestArrived': RequestArrived, 'InputEncoded': InputEncoded, 'WorkCompleted': WorkCompleted, 'TokenSelected': TokenSelected, 'TokenCommitted': TokenCommitted, 'TokenDelivered': TokenDelivered, 'RequestFinished': RequestFinished, 'RunEvent': RunEvent, 'NumericalTrace': NumericalTrace, 'RunRecord': RunRecord, 'Capabilities': Capabilities, 'ApiError': ApiError}
for model in MODELS.values():
    model._definitions = SCHEMAS
    model._registry = MODELS
